import{_ as r,a0 as o,w as p,s as l,I as t,x as e,a1 as i,A as m,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse(`{"title":"在 Linux 下使用 RAID（九）：如何使用 ‘Mdadm’ 工具管理軟件 RAID | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 下使用 RAID（九）：如何使用 ‘Mdadm’ 工具管理軟件 RAID | LCTT (RAID) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 下使用 RAID（九）：如何使用 ‘Mdadm’ 工具管理軟件 RAID | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 下使用 RAID（九）：如何使用 ‘Mdadm’ 工具管理軟件 RAID | LCTT (RAID) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RAID/Part 9 - How to Manage Software RAID's in Linux with 'Mdadm' Tool","title":"在 Linux 下使用 RAID（九）：如何使用 ‘Mdadm’ 工具管理軟件 RAID","tag":"RAID","desc":""},"relativePath":"RAID/Part 9 - How to Manage Software RAID's in Linux with 'Mdadm' Tool.md","filePath":"[post].md"}`),s={name:"RAID/Part 9 - How to Manage Software RAID's in Linux with 'Mdadm' Tool.md"};function R(u,d,w,A,D,I){const a=o("Link");return p(),l("div",null,[d[21]||(d[21]=t("h1",{id:"在-linux-下使用-raid-九-如何使用-mdadm-工具管理軟件-raid",tabindex:"-1"},[e("在 Linux 下使用 RAID（九）：如何使用 ‘Mdadm’ 工具管理軟件 RAID "),t("a",{class:"header-anchor",href:"#在-linux-下使用-raid-九-如何使用-mdadm-工具管理軟件-raid","aria-label":"Permalink to “在 Linux 下使用 RAID（九）：如何使用 ‘Mdadm’ 工具管理軟件 RAID”"},"​")],-1)),t("p",null,[d[1]||(d[1]=e("無論你以前有沒有使用 RAID 陣列的經驗，以及是否完成了 ",-1)),i(a,{href:"https://linux.cn/article-6085-1.html"},{default:m(()=>[...d[0]||(d[0]=[e("此 RAID 系列",-1)])]),_:1}),d[2]||(d[2]=e(" 的所有教程，一旦你在 Linux 中熟悉了 ",-1)),d[3]||(d[3]=t("code",null,"mdadm --manage",-1)),d[4]||(d[4]=e(" 命令的使用，管理軟件 RAID 將不是很複雜的任務。",-1))]),d[22]||(d[22]=n(`<p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Manage-Raid-with-Mdadm-Tool-in-Linux.jpg" alt="在 Linux 中使用 mdadm 管理 RAID 設備 - 第9部分"></p><p><em>在 Linux 中使用 mdadm 管理 RAID 設備 - 第9部分</em></p><p>在本教程中，我們會再介紹此工具提供的功能，這樣當你需要它，就可以派上用場。</p><h4 id="raid-測試方案" tabindex="-1">RAID 測試方案 <a class="header-anchor" href="#raid-測試方案" aria-label="Permalink to “RAID 測試方案”">​</a></h4><p>在本系列的最後一篇文章中，我們將使用一個簡單的 RAID 1（鏡像）陣列，它由兩個 8GB 的磁盤（/dev/sdb 和 /dev/sdc）和一個備用設備（/dev/sdd）來演示，但在此使用的方法也適用於其他類型的配置。也就是説，放心去用吧，把這個頁面添加到瀏覽器的書籤，然後讓我們開始吧。</p><h3 id="瞭解-mdadm-的選項和使用方法" tabindex="-1">瞭解 mdadm 的選項和使用方法 <a class="header-anchor" href="#瞭解-mdadm-的選項和使用方法" aria-label="Permalink to “瞭解 mdadm 的選項和使用方法”">​</a></h3><p>幸運的是，mdadm 有一個內建的 <code>--help</code> 參數來對每個主要的選項提供説明文檔。</p><p>因此，讓我們開始輸入：</p><pre><code># mdadm --manage --help
</code></pre><p>就會使我們看到 <code>mdadm --manage</code> 能夠執行哪些任務：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/mdadm-Usage-in-Linux.png" alt="Manage RAID with mdadm Tool"></p><p><em>使用 mdadm 工具來管理 RAID</em></p><p>正如我們在上面的圖片看到，管理一個 RAID 陣列可以在任意時間執行以下任務：</p><ul><li>（重新）將設備添加到陣列中</li><li>把設備標記為故障</li><li>從陣列中刪除故障設備</li><li>使用備用設備更換故障設備</li><li>先創建部分陣列</li><li>停止陣列</li><li>標記陣列為 ro（只讀）或 rw（讀寫）</li></ul><h3 id="使用-mdadm-工具管理-raid-設備" tabindex="-1">使用 mdadm 工具管理 RAID 設備 <a class="header-anchor" href="#使用-mdadm-工具管理-raid-設備" aria-label="Permalink to “使用 mdadm 工具管理 RAID 設備”">​</a></h3><p>需要注意的是，如果用户忽略 <code>--manage</code> 選項，mdadm 默認使用管理模式。請記住這一點，以避免出現最壞的情況。</p><p>上圖中的高亮文本顯示了管理 RAID 的基本語法：</p><pre><code># mdadm --manage RAID options devices
</code></pre><p>讓我們來演示幾個例子。</p><h4 id="​例1-為-raid-陣列添加設備" tabindex="-1">​例1：為 RAID 陣列添加設備 <a class="header-anchor" href="#​例1-為-raid-陣列添加設備" aria-label="Permalink to “​例1：為 RAID 陣列添加設備”">​</a></h4><p>你通常會添加新設備來更換故障的設備，或者使用空閒的分區以便在出現故障時能及時替換：</p><pre><code># mdadm --manage /dev/md0 --add /dev/sdd1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Add-Device-to-Raid-Array.png" alt="Add Device to Raid Array"></p><p><em>添加設備到 Raid 陣列</em></p><h4 id="​例2-把一個-raid-設備標記為故障並從陣列中移除" tabindex="-1">​例2：把一個 RAID 設備標記為故障並從陣列中移除 <a class="header-anchor" href="#​例2-把一個-raid-設備標記為故障並從陣列中移除" aria-label="Permalink to “​例2：把一個 RAID 設備標記為故障並從陣列中移除”">​</a></h4><p>在從邏輯陣列中刪除該設備前，這是強制性的步驟，然後才能從機器中取出它 - 注意順序（如果弄錯了這些步驟，最終可能會造成實際設備的損害）：</p><pre><code># mdadm --manage /dev/md0 --fail /dev/sdb1
</code></pre>`,27)),t("p",null,[d[6]||(d[6]=e("請注意在前面的例子中，知道如何添加備用設備來自動更換出現故障的磁盤。在此之後，",-1)),i(a,{href:"https://linux.cn/article-6448-1.html"},{default:m(()=>[...d[5]||(d[5]=[e("恢復和重建 raid 數據",-1)])]),_:1}),d[7]||(d[7]=e(" 就開始了：",-1))]),d[23]||(d[23]=n(`<p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Recover-and-Rebuild-Raid-Data.png" alt="Recover and Rebuild Raid Data"></p><p><em>恢復和重建 raid 數據</em></p><p>一旦設備已被手動標記為故障，你就可以安全地從陣列中刪除它：</p><pre><code># mdadm --manage /dev/md0 --remove /dev/sdb1
</code></pre><h4 id="例3-重新添加設備-來替代陣列中已經移除的設備" tabindex="-1">例3：重新添加設備，來替代陣列中已經移除的設備 <a class="header-anchor" href="#例3-重新添加設備-來替代陣列中已經移除的設備" aria-label="Permalink to “例3：重新添加設備，來替代陣列中已經移除的設備”">​</a></h4><p>到現在為止，我們有一個工作的 RAID 1 陣列，它包含了2個活動的設備：/dev/sdc1 和 /dev/sdd1。現在讓我們試試重新添加 /dev/sdb1 到/dev/md0：</p><pre><code># mdadm --manage /dev/md0 --re-add /dev/sdb1
</code></pre><p>我們會碰到一個錯誤:</p><pre><code># mdadm: --re-add for /dev/sdb1 to /dev/md0 is not possible
</code></pre><p>因為陣列中的磁盤已經達到了最大的數量。因此，我們有兩個選擇：a）將 /dev/sdb1 添加為備用的，如例1；或 b）從陣列中刪除 /dev/sdd1 然後重新添加 /dev/sdb1。</p><p>我們選擇選項 b），先停止陣列然後重新啓動：</p><pre><code># mdadm --stop /dev/md0
# mdadm --assemble /dev/md0 /dev/sdb1 /dev/sdc1
</code></pre><p>如果上面的命令不能成功添加 /dev/sdb1 到陣列中，使用例1中的命令來完成。</p><p>mdadm 能檢測到新添加的設備並將其作為備用設備，當添加完成後它會開始重建數據，它也被認為是 RAID 中的活動設備：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Raid-Rebuild-Status.png" alt="Raid Rebuild Status"></p><p><em>重建 Raid 的狀態</em></p><h4 id="例4-使用特定磁盤更換-raid-設備" tabindex="-1">例4：使用特定磁盤更換 RAID 設備 <a class="header-anchor" href="#例4-使用特定磁盤更換-raid-設備" aria-label="Permalink to “例4：使用特定磁盤更換 RAID 設備”">​</a></h4><p>在陣列中使用備用磁盤更換磁盤很簡單：</p><pre><code># mdadm --manage /dev/md0 --replace /dev/sdb1 --with /dev/sdd1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Replace-Raid-device.png" alt="Replace Raid Device"></p><p><em>更換 Raid 設備</em></p><p>這會導致 <code>--replace</code> 指定的設備被標記為故障，而 <code>--with</code>指定的設備添加到 RAID 中來替代它：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Check-Raid-Rebuild-Status.png" alt="Check Raid Rebuild Status"></p><p><em>檢查 Raid 重建狀態</em></p><h4 id="​例5-標記-raid-陣列為-ro-或-rw" tabindex="-1">​例5：標記 RAID 陣列為 ro 或 rw <a class="header-anchor" href="#​例5-標記-raid-陣列為-ro-或-rw" aria-label="Permalink to “​例5：標記 RAID 陣列為 ro 或 rw”">​</a></h4><p>創建陣列後，你必須在它上面創建一個文件系統並將其掛載到一個目錄下才能使用它。你可能不知道，RAID 也可以被設置為 ro，使其只讀；或者設置為 rw，就可以同時寫入了。</p><p>要標記該設備為 ro，首先需要將其卸載：</p><pre><code># umount /mnt/raid1
# mdadm --manage /dev/md0 --readonly
# mount /mnt/raid1
# touch /mnt/raid1/test1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Set-Permissions-on-Raid-Array.png" alt="Set Permissions on Raid Array"></p><p><em>在 RAID 陣列上設置權限</em></p><p>要配置陣列允許寫入操作需要使用 <code>--readwrite</code> 選項。請注意，在設置 rw 標誌前，你需要先卸載設備並停止它：</p><pre><code># umount /mnt/raid1
# mdadm --manage /dev/md0 --stop
# mdadm --assemble /dev/md0 /dev/sdc1 /dev/sdd1
# mdadm --manage /dev/md0 --readwrite
# touch /mnt/raid1/test2
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Allow-Write-Permission-on-Raid.png" alt="Allow Read Write Permission on Raid"></p><p><em>配置 Raid 允許讀寫操作</em></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在本系列中，我們已經解釋瞭如何建立一個在企業環境中使用的軟件 RAID 陣列。如果你按照這些文章所提供的例子進行配置，在 Linux 中你會充分領會到軟件 RAID 的價值。</p><p>如果你碰巧任何問題或有建議，請隨時使用下面的方式與我們聯繫。</p><hr>`,38)),t("p",null,[d[9]||(d[9]=e("via: ",-1)),i(a,{href:"http://www.tecmint.com/manage-software-raid-devices-in-linux-with-mdadm/"},{default:m(()=>[...d[8]||(d[8]=[e("http://www.tecmint.com/manage-software-raid-devices-in-linux-with-mdadm/",-1)])]),_:1})]),t("p",null,[d[13]||(d[13]=e("作者：",-1)),i(a,{href:"http://www.tecmint.com/author/gacanepa/"},{default:m(()=>[...d[10]||(d[10]=[e("GABRIEL CÁNEPA",-1)])]),_:1}),d[14]||(d[14]=e(" 譯者：",-1)),i(a,{href:"https://github.com/strugglingyouth"},{default:m(()=>[...d[11]||(d[11]=[e("strugglingyouth",-1)])]),_:1}),d[15]||(d[15]=e(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:m(()=>[...d[12]||(d[12]=[e("wxy",-1)])]),_:1})]),t("p",null,[d[18]||(d[18]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:m(()=>[...d[16]||(d[16]=[e("LCTT",-1)])]),_:1}),d[19]||(d[19]=e(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:m(()=>[...d[17]||(d[17]=[e("Linux中國",-1)])]),_:1}),d[20]||(d[20]=e(" 榮譽推出",-1))])])}const v=r(s,[["render",R]]);export{g as __pageData,v as default};
